<script lang="ts">
  import { onMount } from 'svelte';
  import Icon from './Icon.svelte';
  import { locale } from '$lib/i18n';
  export let theme: 'light' | 'dark' = 'light';
  export let onThemeChange: (theme: 'light' | 'dark') => void;
  export let motionEnabled = true;
  export let onMotionChange: (enabled: boolean) => void = () => {};
  let units: 'metric' | 'imperial' = 'metric';
  let language: 'fa' | 'en' = 'fa';
  $: ui = $locale === 'en' ? {
    title: 'Settings', heading: 'App settings', intro: 'Tune units and display behavior.', display: 'Calculation display', displayHint: 'Units shown in forms and results.', units: 'Unit system', metric: 'Metric (SI)', imperial: 'Imperial', language: 'Language', appearance: 'Appearance', appearanceHint: 'Color and contrast for the workspace.', light: 'Light', dark: 'Dark', device: 'Stored on this device.', motion: 'Interface motion', motionHint: 'Page and sheet transitions.', enabled: 'Enabled', disabled: 'Disabled', data: 'Data sources', dataHint: 'Component and aircraft records are bundled for offline use.', components: 'Base components', aircraft: 'Aircraft profiles', sources: 'Source groups'
  } : {
    title: 'تنظیمات', heading: 'تنظیمات برنامه', intro: 'واحدها و رفتار نمایش را تنظیم کنید.', display: 'نمایش محاسبات', displayHint: 'واحدهایی که در فرم و نتیجه دیده می‌شوند.', units: 'سیستم واحد', metric: 'متریک (SI)', imperial: 'امپریال', language: 'زبان', appearance: 'ظاهر برنامه', appearanceHint: 'رنگ و کنتراست محیط کار.', light: 'روشن', dark: 'تیره', device: 'تنظیمات در همین دستگاه ذخیره می‌شود.', motion: 'حرکت رابط', motionHint: 'ورود صفحه‌ها و بازشدن پنجره‌ها.', enabled: 'فعال', disabled: 'خاموش', data: 'منابع داده', dataHint: 'فهرست قطعات و مدل‌های پرنده به‌صورت آفلاین همراه برنامه نگه‌داری می‌شود.', components: 'قطعات پایه', aircraft: 'پروفایل پرنده', sources: 'منابع خام'
  };
  onMount(() => {
    const storedUnits = localStorage.getItem('open-ecalc.units');
    const storedLanguage = localStorage.getItem('open-ecalc.language');
    if (storedUnits === 'metric' || storedUnits === 'imperial') units = storedUnits;
    const detected: 'fa' | 'en' = navigator.languages?.some((item) => item.toLowerCase().startsWith('fa')) ? 'fa' : 'en';
    language = storedLanguage === 'fa' || storedLanguage === 'en' ? storedLanguage : detected;
    applyLanguage(language);
  });
  function persist() { localStorage.setItem('open-ecalc.units', units); }
  function applyLanguage(next: 'fa' | 'en') {
    language = next;
    localStorage.setItem('open-ecalc.language', next);
    localStorage.setItem('open-ecalc.locale', next);
    locale.set(next);
    document.documentElement.lang = next;
    document.documentElement.dir = next === 'fa' ? 'rtl' : 'ltr';
    window.dispatchEvent(new CustomEvent('open-ecalc-languagechange', { detail: next }));
  }
</script>

<section class="settings-page" aria-labelledby="settings-title">
