  <div class="settings-grid">
    <section class="settings-card"><div class="settings-card__title"><Icon name="sliders" size={23} /><div><h2>{ui.display}</h2><p>{ui.displayHint}</p></div></div><label><span>{ui.units}</span><select bind:value={units} on:change={persist}><option value="metric">{ui.metric}</option><option value="imperial">{ui.imperial}</option></select></label><label><span>{ui.language}</span><select value={language} on:change={(event) => applyLanguage((event.currentTarget as HTMLSelectElement).value as 'fa' | 'en')}><option value="fa">فارسی</option><option value="en">English</option></select></label></section>
    <section class="settings-card"><div class="settings-card__title"><Icon name={theme === 'dark' ? 'moon' : 'sun'} size={23} /><div><h2>{ui.appearance}</h2><p>{ui.appearanceHint}</p></div></div><label class="theme-choice"><span class="theme-swatch" class:dark={theme === 'dark'}></span><span>{theme === 'light' ? ui.light : ui.dark}</span><input class="theme-checkbox" type="checkbox" checked={theme === 'dark'} on:change={() => onThemeChange(theme === 'light' ? 'dark' : 'light')} /><span class="theme-switch" aria-hidden="true"><i></i></span></label><p class="settings-note">{ui.device}</p></section>
    <section class="settings-card"><div class="settings-card__title"><Icon name="sliders" size={23} /><div><h2>{ui.motion}</h2><p>{ui.motionHint}</p></div></div><label class="theme-choice"><span class="motion-swatch"><Icon name="spark" size={17} /></span><span>{motionEnabled ? ui.enabled : ui.disabled}</span><input class="theme-checkbox" type="checkbox" checked={motionEnabled} on:change={() => onMotionChange(!motionEnabled)} /><span class="theme-switch" aria-hidden="true"><i></i></span></label></section>
    <section class="settings-card settings-card--wide"><div class="settings-card__title"><Icon name="components" size={23} /><div><h2>{ui.data}</h2><p>{ui.dataHint}</p></div></div><div class="data-row"><span>{ui.components}</span><strong class="data">۸</strong></div><div class="data-row"><span>{ui.aircraft}</span><strong class="data">۱۵۹</strong></div><div class="data-row"><span>{ui.sources}</span><strong class="data">۵</strong></div></section>
  </div>
</section>

